with parsed as (select id, host, log_ts, level, status_code, payload_json, get_json_object(payload_json, '$.user.id') as user_id, size(context) as num_context, get_json_object(payload_json, '$.duration') as duration_text, coalesce(context['trace'], 'unknown') as trace_or_default, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec from app_logs) select level, percentile_approx(duration_sec, array(0.25, 0.5, 0.75)) as duration_sec_quartiles, sum(case when host = 'h4' then status_code else 0 end) as h4_status_code, size(collect_set(level)) as num_levels, bit_or(status_code) as status_code_bit_or, max(log_ts) as ended_at, approx_percentile(status_code, array(0.25, 0.5, 0.75)) as status_code_quartiles from parsed group by level;
